vec2 setup_st(in vec2 coord, in vec2 res){
    return coord / res.y;
}

vec2 pixelized(in vec2 st) {
    float PIXEL_SCALE = 128.;

    return floor(st * PIXEL_SCALE) / PIXEL_SCALE;
}


float distortion_fn1(float x) {
    return cos(x * 24. + iTime) * 0.01;
}

float distortion_fn2(float x) {
    return sin(x * 16. + iTime * 2.) * 0.01;
}

vec2 distorted(in vec2 st) {

    st.y += distortion_fn1(st.x); // comment this line out to see different output

    st.x += distortion_fn2(st.y); // comment this line out to see different output

    return st;
}


vec4 checkerboard_pattern(in vec2 st)
{
    vec3 C_BLACK = vec3(0.5);
    vec3 C_WHITE = vec3(0.75);

    vec2 ft = floor(st * 8.);

    bool x_even = mod(ft.x, 2.0) == 0.;
    bool y_even = mod(ft.y, 2.0) == 0.;

    vec3 color = x_even == y_even ? C_WHITE : C_BLACK;

    return vec4(color, 1.0);
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 st = setup_st(fragCoord.xy, iResolution.xy);

    st = pixelized(st); // comment this line out to see different output

    st = distorted(st); // comment this line out to see different output

    fragColor = checkerboard_pattern(st);
}
